import os,json,struct,re
from volatility3.plugins.windows import windows
class Ptrscan(windows.Windows):
 def _generator(self):
  out=[]
  for sn,dn,w,wn in self.list_windows(self.context,self.config_path,self.config['kernel']):
   if w.vol.offset!=0xbd5b448f45b0:continue
   sp=w.subPointer.dereference();lay=self.context.layers[sp.vol.layer_name];root=lay.read(sp.vol.offset,4096,pad=True)
   queue=[];seen=set()
   def ptrs(b,path):
    for off in range(0,len(b)-7,8):
     q=struct.unpack_from('<Q',b,off)[0]
     if 0x100000<=q<0x800000000000 and q not in seen:queue.append((q,path+[off]))
   ptrs(root,[])
   while queue:
    q,path=queue.pop(0);seen.add(q)
    try:b=lay.read(q,16384,pad=False)
    except:continue
    u=[[m.start(),m.group().decode('utf-16le','ignore')] for m in re.finditer(rb'(?:[\x20-\x7e]\x00){3,}',b)]
    a=[[m.start(),m.group().decode('ascii','ignore')] for m in re.finditer(rb'[\x20-\x7e]{4,}',b)]
    if u or a:out.append({'path':path,'address':hex(q),'utf16':u,'ascii':a})
    if len(path)<2:ptrs(b,path)
   json.dump(out,open(os.environ['OUTJSON'],'w'),indent=2)
  yield from super()._generator()
PY
